package ar.gob.municipalidad.rentas;

import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.*;
import java.time.*;
import java.util.*;

@Service
class AdjustmentService {
    private final AdjustmentRepository adjustments;private final DebtRepository debts;private final PaymentPlanDebtRepository planDebts;private final PaymentPlanRepository plans;private final CurrentIdentity identity;private final AuditService audit;private final EventosDeDominio events;
    AdjustmentService(AdjustmentRepository adjustments,DebtRepository debts,PaymentPlanDebtRepository planDebts,PaymentPlanRepository plans,CurrentIdentity identity,AuditService audit,EventosDeDominio events){this.adjustments=adjustments;this.debts=debts;this.planDebts=planDebts;this.plans=plans;this.identity=identity;this.audit=audit;this.events=events;}
    @Transactional AdjustmentRequest create(ApiDtos.CreateAdjustmentRequest r){Debt debt=debt(r.debtId());CatalogService.requireConflict(debt.admiteAjuste(),"DEBT_NOT_ADJUSTABLE","La deuda no admite ajustes");CatalogService.requireConflict(!planDebts.existsByDebtIdAndStatus(debt.id,PaymentPlanDebtStatus.ACTIVE)&&!plans.existsByDebtIdAndStatus(debt.id,PaymentPlanStatus.ACTIVE),"DEBT_IN_ACTIVE_PAYMENT_PLAN","No se ajusta directamente una deuda incluida en un plan activo");AdjustmentRequest a=new AdjustmentRequest();a.debtId=debt.id;a.type=r.type();a.amount=PaymentService.money(r.amount());a.reason=r.reason();a.status=AdjustmentStatus.PENDING_APPROVAL;a.requestedBy=identity.get().userId();a.requestedAt=OffsetDateTime.now();adjustments.save(a);audit.record("AdjustmentRequest",a.id,"DEBT_ADJUSTMENT_REQUESTED",a);return a;}
    AdjustmentRequest get(Long id){return adjustments.findById(id).orElseThrow(()->CatalogService.notFound("Ajuste"));}
    @Transactional AdjustmentRequest approve(Long id,String observation){AdjustmentRequest a=adjustments.findByIdForUpdate(id).orElseThrow(()->CatalogService.notFound("Ajuste"));CatalogService.require(a.status==AdjustmentStatus.PENDING_APPROVAL,"ADJUSTMENT_NOT_PENDING","El ajuste no está pendiente");audit.requireDifferentActor("AdjustmentRequest",a.id,a.requestedBy);Debt debt=debts.findByIdForUpdate(a.debtId).orElseThrow(()->CatalogService.notFound("Deuda"));BigDecimal nextCurrent=switch(a.type){case DISCOUNT->debt.currentAmount.subtract(a.amount);case SURCHARGE,INTEREST->debt.currentAmount.add(a.amount);case CORRECTION->a.amount;};BigDecimal delta=nextCurrent.subtract(debt.currentAmount);BigDecimal nextOutstanding=debt.outstandingBalance.add(delta);BigDecimal paid=debt.currentAmount.subtract(debt.outstandingBalance);CatalogService.require(nextCurrent.compareTo(paid)>=0&&nextOutstanding.signum()>=0,"ADJUSTMENT_BELOW_PAID_AMOUNT","El ajuste reduciría la deuda por debajo de lo pagado");a.previousDebtAmount=debt.currentAmount;a.newDebtAmount=nextCurrent;a.status=AdjustmentStatus.APPROVED;a.resolvedBy=identity.get().userId();a.resolvedAt=OffsetDateTime.now();a.resolutionReason=observation;debt.ajustar(nextCurrent,nextOutstanding);debt.updatedAt=OffsetDateTime.now();audit.record("AdjustmentRequest",a.id,"DEBT_ADJUSTED",a);events.deudaAjustada(debt,a);return a;}
    @Transactional AdjustmentRequest reject(Long id,String reason){AdjustmentRequest a=adjustments.findByIdForUpdate(id).orElseThrow(()->CatalogService.notFound("Ajuste"));CatalogService.require(a.status==AdjustmentStatus.PENDING_APPROVAL,"ADJUSTMENT_NOT_PENDING","El ajuste no está pendiente");audit.requireDifferentActor("AdjustmentRequest",a.id,a.requestedBy);a.status=AdjustmentStatus.REJECTED;a.resolutionReason=reason;a.resolvedBy=identity.get().userId();a.resolvedAt=OffsetDateTime.now();audit.record("AdjustmentRequest",a.id,"DEBT_ADJUSTMENT_REJECTED",a);return a;}
    private Debt debt(Long id){return debts.findById(id).orElseThrow(()->CatalogService.notFound("Deuda"));}
}

@Service
class LiquidationRunService {
    private final LiquidationRunRepository runs;private final LiquidationRunItemRepository items;private final TaxConceptRepository concepts;private final TaxpayerRepository taxpayers;private final LiquidationRepository liquidationRepository;private final LiquidationService liquidations;private final LiquidationRunExecutionExecutor executionExecutor;private final LiquidationRunFailureRecorder failureRecorder;private final CurrentIdentity identity;private final AuditService audit;
    LiquidationRunService(LiquidationRunRepository runs,LiquidationRunItemRepository items,TaxConceptRepository concepts,TaxpayerRepository taxpayers,LiquidationRepository liquidationRepository,LiquidationService liquidations,LiquidationRunExecutionExecutor executionExecutor,LiquidationRunFailureRecorder failureRecorder,CurrentIdentity identity,AuditService audit){this.runs=runs;this.items=items;this.concepts=concepts;this.taxpayers=taxpayers;this.liquidationRepository=liquidationRepository;this.liquidations=liquidations;this.executionExecutor=executionExecutor;this.failureRecorder=failureRecorder;this.identity=identity;this.audit=audit;}
    @Transactional LiquidationRun create(ApiDtos.CreateLiquidationRunRequest r){concepts.findById(r.taxConceptId()).orElseThrow(()->CatalogService.notFound("Concepto"));CatalogService.require(!r.dueDate().isBefore(LocalDate.now()),"INVALID_DUE_DATE","El vencimiento no puede estar en el pasado");CatalogService.require(r.items().stream().map(ApiDtos.LiquidationRunItemRequest::taxpayerId).distinct().count()==r.items().size(),"DUPLICATE_RUN_TAXPAYER","La corrida repite un contribuyente");LiquidationRun run=new LiquidationRun();run.taxConceptId=r.taxConceptId();run.period=r.period();run.dueDate=r.dueDate();run.status=LiquidationRunStatus.DRAFT;run.totalItems=r.items().size();run.validItems=run.errorItems=0;run.estimatedTotalAmount=MonetaryAmounts.zero();run.createdBy=identity.get().userId();run.createdAt=OffsetDateTime.now();runs.save(run);for(ApiDtos.LiquidationRunItemRequest input:r.items()){LiquidationRunItem item=new LiquidationRunItem();item.liquidationRunId=run.id;item.taxpayerId=input.taxpayerId();item.taxableBase=input.taxableBase();item.status=LiquidationRunItemStatus.PENDING;items.save(item);}return run;}
    ApiDtos.LiquidationRunDetail detail(Long id){LiquidationRun run=get(id);return new ApiDtos.LiquidationRunDetail(run,items.findByLiquidationRunIdOrderById(id));}
    @Transactional ApiDtos.LiquidationRunDetail preview(Long id){LiquidationRun run=get(id);CatalogService.require(run.status==LiquidationRunStatus.DRAFT,"RUN_NOT_DRAFT","Sólo se previsualiza una corrida borrador");run.validItems=run.errorItems=0;run.estimatedTotalAmount=MonetaryAmounts.zero();for(LiquidationRunItem item:items.findByLiquidationRunIdOrderById(id)){item.previewAmount=null;item.errorCode=item.errorMessage=null;try{taxpayers.findById(item.taxpayerId).orElseThrow(()->CatalogService.notFound("Contribuyente"));CatalogService.require(!liquidationRepository.existsByTaxpayerIdAndTaxConceptIdAndPeriod(item.taxpayerId,run.taxConceptId,run.period),"DUPLICATE_LIQUIDATION","Ya existe una liquidación para el contribuyente, concepto y período");ApiDtos.LiquidationPreview preview=liquidations.preview(request(run,item));if(run.configurationId==null){run.configurationId=preview.taxConfigurationId();run.configurationVersion=preview.configurationVersion();}CatalogService.require(run.configurationId.equals(preview.taxConfigurationId())&&run.configurationVersion==preview.configurationVersion(),"RUN_CONFIGURATION_CHANGED","La configuración cambió durante la previsualización");item.previewAmount=preview.finalAmount();item.status=LiquidationRunItemStatus.VALID;run.validItems++;run.estimatedTotalAmount=run.estimatedTotalAmount.add(preview.finalAmount());}catch(BusinessException ex){item.status=LiquidationRunItemStatus.ERROR;item.errorCode=ex.code;item.errorMessage=ex.getMessage();run.errorItems++;}}return detail(id);}
    @Transactional LiquidationRun submit(Long id){LiquidationRun run=runs.findByIdForUpdate(id).orElseThrow(()->CatalogService.notFound("Corrida de liquidación"));CatalogService.require(run.status==LiquidationRunStatus.DRAFT&&run.validItems>0,"RUN_NOT_READY","La corrida debe previsualizarse y tener ítems válidos");run.status=LiquidationRunStatus.PENDING_APPROVAL;run.submittedBy=identity.get().userId();run.submittedAt=OffsetDateTime.now();return run;}
    @Transactional LiquidationRun approve(Long id,String observation){LiquidationRun run=runs.findByIdForUpdate(id).orElseThrow(()->CatalogService.notFound("Corrida de liquidación"));CatalogService.require(run.status==LiquidationRunStatus.PENDING_APPROVAL,"RUN_NOT_PENDING","La corrida no está pendiente");audit.requireDifferentActor("LiquidationRun",run.id,run.createdBy,run.submittedBy);run.status=LiquidationRunStatus.APPROVED;run.resolvedBy=identity.get().userId();run.resolvedAt=OffsetDateTime.now();audit.record("LiquidationRun",run.id,"LIQUIDATION_RUN_APPROVED",run);return run;}
    @Transactional LiquidationRun reject(Long id,String reason){LiquidationRun run=runs.findByIdForUpdate(id).orElseThrow(()->CatalogService.notFound("Corrida de liquidación"));CatalogService.require(run.status==LiquidationRunStatus.PENDING_APPROVAL,"RUN_NOT_PENDING","La corrida no está pendiente");audit.requireDifferentActor("LiquidationRun",run.id,run.createdBy,run.submittedBy);run.status=LiquidationRunStatus.REJECTED;run.resolvedBy=identity.get().userId();run.resolvedAt=OffsetDateTime.now();audit.record("LiquidationRun",run.id,"LIQUIDATION_RUN_REJECTED",run);return run;}
    LiquidationRun execute(Long id){try{return executionExecutor.execute(id);}catch(LiquidationRunItemExecutionFailure failure){if(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive())throw failure;recordExecutionFailure(id,failure);throw failure.businessException;}}
    void recordExecutionFailure(Long id,LiquidationRunItemExecutionFailure failure){failureRecorder.record(id,failure.itemId,failure.businessException);}
    private LiquidationRun get(Long id){return runs.findById(id).orElseThrow(()->CatalogService.notFound("Corrida de liquidación"));}
    private ApiDtos.LiquidationRequest request(LiquidationRun run,LiquidationRunItem item){return new ApiDtos.LiquidationRequest(item.taxpayerId,run.taxConceptId,run.period,item.taxableBase,run.dueDate);}
}

@Service
class LiquidationRunExecutionExecutor {
    private final LiquidationRunRepository runs;private final LiquidationRunItemRepository items;private final LiquidationRepository liquidationRepository;private final LiquidationService liquidations;private final AuditService audit;
    LiquidationRunExecutionExecutor(LiquidationRunRepository runs,LiquidationRunItemRepository items,LiquidationRepository liquidationRepository,LiquidationService liquidations,AuditService audit){this.runs=runs;this.items=items;this.liquidationRepository=liquidationRepository;this.liquidations=liquidations;this.audit=audit;}
    @Transactional(propagation=org.springframework.transaction.annotation.Propagation.REQUIRED)
    LiquidationRun execute(Long id){LiquidationRun run=runs.findByIdForUpdate(id).orElseThrow(()->CatalogService.notFound("Corrida de liquidación"));CatalogService.require(run.status==LiquidationRunStatus.APPROVED,"RUN_NOT_APPROVED","La corrida debe estar aprobada");for(LiquidationRunItem item:items.findByLiquidationRunIdOrderById(id)){if(item.status!=LiquidationRunItemStatus.VALID)continue;try{Liquidation liquidation=liquidations.create(new ApiDtos.LiquidationRequest(item.taxpayerId,run.taxConceptId,run.period,item.taxableBase,run.dueDate));liquidationRepository.flush();CatalogService.require(liquidation.taxConfigurationId.equals(run.configurationId)&&liquidation.configurationVersion==run.configurationVersion,"RUN_CONFIGURATION_CHANGED","La configuración cambió antes de ejecutar");item.liquidationId=liquidation.id;item.status=LiquidationRunItemStatus.LIQUIDATED;}catch(BusinessException failure){throw new LiquidationRunItemExecutionFailure(item.id,failure);}catch(DataIntegrityViolationException failure){if(!isDuplicateLiquidation(failure))throw failure;throw new LiquidationRunItemExecutionFailure(item.id,new BusinessException("DUPLICATE_LIQUIDATION","Ya existe una liquidación para el contribuyente, concepto y período",422));}}run.status=LiquidationRunStatus.EXECUTED;audit.record("LiquidationRun",run.id,"LIQUIDATION_RUN_EXECUTED",run);return run;}
    private boolean isDuplicateLiquidation(DataIntegrityViolationException failure){for(Throwable cause=failure;cause!=null;cause=cause.getCause())if(cause instanceof org.hibernate.exception.ConstraintViolationException violation)return "uk_liquidation_business".equals(violation.getConstraintName());return false;}
}

class LiquidationRunItemExecutionFailure extends RuntimeException {
    final Long itemId;final BusinessException businessException;
    LiquidationRunItemExecutionFailure(Long itemId,BusinessException businessException){super(businessException);this.itemId=itemId;this.businessException=businessException;}
}

@Service
class LiquidationRunFailureRecorder {
    private static final String ABORTED_CODE="LIQUIDATION_RUN_ABORTED";
    private static final String ABORTED_MESSAGE="La corrida se canceló porque falló otro ítem; no se emitieron liquidaciones";
    private final LiquidationRunRepository runs;private final LiquidationRunItemRepository items;private final AuditService audit;
    LiquidationRunFailureRecorder(LiquidationRunRepository runs,LiquidationRunItemRepository items,AuditService audit){this.runs=runs;this.items=items;this.audit=audit;}
    @Transactional(propagation=org.springframework.transaction.annotation.Propagation.REQUIRES_NEW)
    LiquidationRun record(Long runId,Long failedItemId,BusinessException failure){LiquidationRun run=runs.findByIdForUpdate(runId).orElseThrow(()->CatalogService.notFound("Corrida de liquidación"));if(run.status==LiquidationRunStatus.FAILED)return run;CatalogService.require(run.status==LiquidationRunStatus.APPROVED,"RUN_NOT_APPROVED","La corrida debe estar aprobada");for(LiquidationRunItem item:items.findByLiquidationRunIdOrderById(runId)){if(item.status!=LiquidationRunItemStatus.VALID)continue;item.status=LiquidationRunItemStatus.ERROR;item.errorCode=Objects.equals(item.id,failedItemId)?failure.code:ABORTED_CODE;item.errorMessage=Objects.equals(item.id,failedItemId)?failure.getMessage():ABORTED_MESSAGE;item.liquidationId=null;run.validItems--;run.errorItems++;if(item.previewAmount!=null)run.estimatedTotalAmount=MonetaryAmounts.normalize(run.estimatedTotalAmount.subtract(item.previewAmount));}run.status=LiquidationRunStatus.FAILED;audit.record("LiquidationRun",run.id,"LIQUIDATION_RUN_EXECUTION_FAILED",run);return run;}
}
